function validate([expression]) {
  if (typeof expression !== 'string' || expression.length < 1 || expression.length > 20000) return 'expression needs 1 to 20000 characters.';
  if (/[^()&|!tf,]/.test(expression)) return 'expression may only use ( ) & | ! t f and commas.';
  const bad = 'expression is not a well-formed formula.';
  const open = [];
  let wantFormula = true;
  let finished = false;
  for (let i = 0; i < expression.length; i++) {
    const ch = expression[i];
    if (finished) return bad;
    if (wantFormula) {
      if (ch === 't' || ch === 'f') {
        wantFormula = false;
        if (open.length === 0) finished = true;
      } else if (ch === '!' || ch === '&' || ch === '|') {
        if (expression[i + 1] !== '(') return bad;
        open.push(ch);
        i++;
      } else return bad;
    } else if (ch === ',') {
      if (open[open.length - 1] === '!') return '! takes exactly one formula.';
      wantFormula = true;
    } else if (ch === ')') {
      open.pop();
      if (open.length === 0) finished = true;
    } else return bad;
  }
  return finished ? null : bad;
}

