      if (stack.pop() === 't') {
        hasTrue = true;
      } else {
        hasFalse = true;
      }
    }
    const operator = stack.pop();
    let result;
    if (operator === '!') {
      result = hasFalse;
    } else if (operator === '&') {
      result = !hasFalse;
    } else {
      result = hasTrue;
    }
    stack.push(result ? 't' : 'f');
  }
  return stack.pop() === 't';
}

