function parseBoolExpr(expression) {
  // Repeatedly collapse every innermost group (one that holds only t, f and commas) into a single letter.
  const innermost = /([!&|])\(([tf,]*)\)/g;
  let text = expression;
  while (text.length > 1) {
    text = text.replace(innermost, (_, op, inside) => {
      const values = inside.split(',');
      if (op === '!') return values[0] === 't' ? 'f' : 't';
      if (op === '&') return values.every(v => v === 't') ? 't' : 'f';
      return values.some(v => v === 't') ? 't' : 'f';
    });
  }
  return text === 't';
}

