function generate(rand, size) {
  const large = size === 'large';
  let budget = large ? 9000 : 4 + Math.floor(rand() * 30);
  const maxDepth = large ? 40 : 4;
  const leaf = () => { budget -= 1; return rand() < 0.5 ? 't' : 'f'; };
  const build = (depth) => {
    // A large root never stops early and keeps taking operands until the budget is spent.
    const root = large && depth === 0;
    const stop = root ? 0 : depth === 0 ? 0.05 : 0.3;
    if (depth >= maxDepth || budget < 6 || rand() < stop) return leaf();
    const pick = rand();
    const op = pick < (root ? 0 : 0.25) ? '!' : pick < 0.6 ? '&' : '|';
    budget -= 3;
    if (op === '!') return '!(' + build(depth + 1) + ')';
    const want = root ? Infinity : large ? 2 + Math.floor(rand() * 8) : 1 + Math.floor(rand() * 4);
    const parts = [build(depth + 1)];
    while (parts.length < want && budget > 2) {
      budget -= 1;
      parts.push(build(depth + 1));
    }
    return op + '(' + parts.join(',') + ')';
  };
  return [build(0)];
}
